// Users bundles the /users handlers.
type Users struct {
	MySQL    *sql.DB
	Sessions *auth.Manager
	AdminDB  *admindb.DB
}

// QuotaReportPath is the on-disk location of the generated quota report.
var QuotaReportPath = "/etc/openpanel/openpanel/quota_report.json"

type diskUsage struct {
	DiskUsed   interface{} `json:"disk_used"`
	DiskSoft   interface{} `json:"disk_soft"`
	DiskHard   interface{} `json:"disk_hard"`
	InodesUsed interface{} `json:"inodes_used"`
	InodesSoft interface{} `json:"inodes_soft"`
	InodesHard interface{} `json:"inodes_hard"`
}

// readDiskUsageAll reads the quota report generated by `opencli
// user-quota` (regenerating it is left to that existing cron/on-demand
// mechanism -- this just reads whatever is currently on disk). It does not
// itself shell out to regenerate a missing report, since triggering a
// system-wide quota scan as a side effect of a page load is a heavier
// behavior worth a deliberate follow-up decision rather than doing it
// silently here.
func readDiskUsageAll() map[string]diskUsage {
	out := map[string]diskUsage{}
	raw, err := os.ReadFile(QuotaReportPath)
	if err != nil {
		return out
	}
	var parsed struct {
		Users []struct {
			Username   string      `json:"username"`
			DiskUsed   interface{} `json:"disk_used"`
			DiskSoft   interface{} `json:"disk_soft"`
			DiskHard   interface{} `json:"disk_hard"`
			InodesUsed interface{} `json:"inodes_used"`
			InodesSoft interface{} `json:"inodes_soft"`
			InodesHard interface{} `json:"inodes_hard"`
		} `json:"users"`
	}
	if json.Unmarshal(raw, &parsed) != nil {
		return out
	}
	for _, u := range parsed.Users {
		if u.Username == "" {
			continue
		}
		out[u.Username] = diskUsage{
			DiskUsed: u.DiskUsed, DiskSoft: u.DiskSoft, DiskHard: u.DiskHard,
			InodesUsed: u.InodesUsed, InodesSoft: u.InodesSoft, InodesHard: u.InodesHard,
		}
	}
	return out
}

// toFloat coerces a disk-quota field (decoded from quota_report.json as
// float64/int/string) to a float64 so the usage-ratio math below can treat
// every field uniformly regardless of its JSON type.
func toFloat(v interface{}) float64 {
	switch t := v.(type) {
	case float64:
		return t
	case int64:
		return float64(t)
	case int:
		return float64(t)
	case string:
		f, _ := strconv.ParseFloat(t, 64)
		return f
	default:
		return 0
	}
}

// statFloat/statString walk a nested map[string]interface{} (a raw
// resource_usage.txt JSON line) along path, using forgiving
// `stat.memory.used.bytes`-style dotted access (missing keys read as zero
// value rather than erroring).
func statFloat(stat map[string]interface{}, path ...string) float64 {
	var cur interface{} = stat
	for _, p := range path {
		m, ok := cur.(map[string]interface{})
		if !ok {
			return 0
		}
		cur = m[p]
	}
	return toFloat(cur)
}

func statString(stat map[string]interface{}, path ...string) string {
	var cur interface{} = stat
	for _, p := range path {
		m, ok := cur.(map[string]interface{})
		if !ok {
			return ""
		}
		cur = m[p]
	}
	s, _ := cur.(string)
	return s
}

// arcCircumference is the SVG progress-ring circumference used throughout
// all.html's mini usage donuts (r=12.5 -> 2*pi*12.5).
const arcCircumference = 78.53981633974483

func arcOffset(percent float64) string {
	return strconv.FormatFloat(arcCircumference*(1-percent/100), 'f', -1, 64)
}

// usageColorClass is the shared red/orange/green/blue/gray threshold
// ladder (>=90/>=80/>=60/>0) used by the usage rings.
func usageColorClass(pct float64) string {
	switch {
	case pct >= 90:
		return "red"
	case pct >= 80:
		return "orange"
	case pct >= 60:
		return "green"
	case pct > 0:
		return "blue"
	default:
		return "gray"
	}
}

// usageWidgetData is the precomputed set of numbers/labels the per-user
// mem/cpu/disk/inodes usage rings need -- built here in Go rather than in
// the template since html/template has no arithmetic operators.
type usageWidgetData struct {
	MemPercent  int
	MemOffset   string
	MemColor    string
	MemTooltip  string
	CPUPercent  int
	CPUOffset   string
	CPUColor    string
	CPUTooltip  string
	HasDiskData bool
	DiskPercent int
	DiskOffset  string
	DiskColor   string
	DiskTooltip string

	InodesPercent int
	InodesOffset  string
	InodesColor   string
	InodesTooltip string
}

// buildUsageWidget computes the Memory/CPU/Disk/Inodes ring math for the
// users list page, including a preserved quirk: a real red/orange/green/
// blue color class is computed for the Memory ring and then immediately
// overridden back to a hardcoded 'gray', so the Memory ring is always gray
// regardless of usage -- the CPU/Disk/Inodes rings don't have this
// override and do color dynamically.
func buildUsageWidget(suspended bool, stat map[string]interface{}, disk diskUsage, hasDisk bool) usageWidgetData {
	memUsedHuman, memTotalHuman := "0 B", "0 B"
	memPct, cpuPct := 0.0, 0.0
	if !suspended && stat != nil {
		memUsedHuman = statString(stat, "memory", "used", "human")
		memTotalHuman = statString(stat, "memory", "total", "human")
		if statFloat(stat, "memory", "total", "bytes") != 0 {
			memPct = statFloat(stat, "memory", "usage_pct")
		}
		cpuPct = statFloat(stat, "cpu", "usage", "pct")
	}

	w := usageWidgetData{
		MemPercent: int(math.Round(memPct)),
		MemOffset:  arcOffset(memPct),
		MemColor:   "gray",
		MemTooltip: fmt.Sprintf("Memory usage: %s / %s", memUsedHuman, memTotalHuman),
		CPUPercent: int(math.Round(cpuPct)),
		CPUOffset:  arcOffset(cpuPct),
		CPUColor:   usageColorClass(cpuPct),
		CPUTooltip: fmt.Sprintf("CPU usage: %v%%", cpuPct),
	}

	if hasDisk {
		diskHard, diskUsed := toFloat(disk.DiskHard), toFloat(disk.DiskUsed)
		diskPct := 0.0
		if diskHard != 0 {
			diskPct = diskUsed / diskHard * 100
		}
		inodesHard, inodesUsed := toFloat(disk.InodesHard), toFloat(disk.InodesUsed)
		inodesPct := 0.0
		if inodesHard != 0 {
			inodesPct = inodesUsed / inodesHard * 100
		}
		inodesOffsetPct := inodesPct
		if inodesOffsetPct > 100 {
			inodesOffsetPct = 100
		}

		w.HasDiskData = true
		w.DiskPercent = int(math.Round(diskPct))
		w.DiskOffset = arcOffset(diskPct)
		w.DiskColor = usageColorClass(diskPct)
		w.DiskTooltip = fmt.Sprintf("Disk usage: %s / %s", humanGB(diskUsed), humanBytesOrInf(diskHard))
		w.InodesPercent = int(math.Round(inodesPct))
		w.InodesOffset = arcOffset(inodesOffsetPct)
		w.InodesColor = usageColorClass(inodesPct)
		w.InodesTooltip = fmt.Sprintf("Inodes usage: %s / %s", humanCount(inodesUsed), humanCountOrInf(inodesHard))
	}

	return w
}

// detailStatsWidget is the precomputed ring data for the user detail page's
// Statistics tab -- a larger set of rings (radius 29, not the list page's
// 12.5) with its own color thresholds, so it's kept separate from
// usageWidgetData rather than shared.
type detailStatsWidget struct {
	DiskUsageRounded string
	DiskOffset       string
	DiskColorClass   string
	DiskUsedHuman    string
	DiskHardHuman    string

	InodesUsageRounded string
	InodesOffset       string
	InodesColorClass   string
	InodesUsedHuman    string
	InodesHardHuman    string

	CPURatioRounded string
	CPUOffset       string
	CPUColor        string
	CPUHumanUsage   string
	CPUHumanTotal   string

	RAMPercentRounded string
	RAMOffset         string
	RAMColor          string
	RAMHumanUsage     string
	RAMHumanTotal     string
}

const detailRingCircumference = 182.212373908208

func detailRingColorClass(pct float64) string {
	switch {
	case pct > 90:
		return "stroke-red-200 dark:stroke-red-500/40"
	case pct > 80:
		return "stroke-orange-200 dark:stroke-orange-500/40"
	case pct > 60:
		return "stroke-blue-200 dark:stroke-blue-500/40"
	default:
		return "stroke-gray-200 dark:stroke-gray-500/40"
	}
}

func detailRingOffset(pctClamped float64) string {
	return strconv.FormatFloat(detailRingCircumference-(detailRingCircumference*pctClamped/100), 'f', -1, 64)
}

func round2(f float64) float64 {
	return math.Round(f*100) / 100
}

func humanBytesOrInf(hard float64) string {
	if hard == 0 {
		return "∞"
	}
	return humanGB(hard)
}

func humanGB(v float64) string {
	return strconv.FormatFloat(round2(v/1024000), 'f', -1, 64) + "GB"
}

func humanCount(v float64) string {
	if v == 0 {
		return "0"
	}
	if v >= 1000000 {
		return strconv.FormatFloat(round2(v/1000000), 'f', -1, 64) + "M"
	}
	return strconv.FormatFloat(v, 'f', -1, 64)
}

func humanCountOrInf(v float64) string {
	if v == 0 {
		return "∞"
	}
	return humanCount(v)
}

func buildDetailStatsWidget(suspended bool, disk diskUsage, stats map[string]interface{}) detailStatsWidget {
	diskUsed, diskHard := toFloat(disk.DiskUsed), toFloat(disk.DiskHard)
	diskPct := 0.0
	if diskHard != 0 {
		diskPct = diskUsed / diskHard * 100
	}
	diskClamped := diskPct
	if diskClamped > 100 {
		diskClamped = 100
	}

	inodesUsed, inodesHard := toFloat(disk.InodesUsed), toFloat(disk.InodesHard)
	inodesPct := 0.0
	if diskHard != 0 {
		inodesPct = inodesUsed / diskHard * 100
	}
	inodesClamped := inodesPct
	if inodesClamped > 100 {
		inodesClamped = 100
	}

	percentCPU, totalCPU, percentMem := 0.0, 100.0, 0.0
	humanCPUUsage, humanCPUTotal := "0 cores", "0 cores"
	humanMemUsage, humanMemTotal := "0B", "0B"
	if !suspended && stats != nil {
		percentCPU = statFloat(stats, "cpu", "usage", "pct")
		if t := statFloat(stats, "cpu", "total", "pct"); t != 0 {
			totalCPU = t
		}
		humanCPUUsage = statString(stats, "cpu", "usage", "human")
		humanCPUTotal = statString(stats, "cpu", "total", "human")
		percentMem = statFloat(stats, "memory", "usage_pct")
		humanMemUsage = statString(stats, "memory", "used", "human")
		humanMemTotal = statString(stats, "memory", "total", "human")
	}
	ratioCPU := percentCPU / totalCPU * 100

	diskUsedHuman := "0B"
	if diskUsed != 0 {
		diskUsedHuman = strconv.FormatFloat(round2(diskUsed/1024000), 'f', -1, 64) + "GB"
	}

	return detailStatsWidget{
		DiskUsageRounded: strconv.FormatFloat(round2(diskClamped), 'f', -1, 64),
		DiskOffset:       detailRingOffset(round2(diskClamped)),
		DiskColorClass:   detailRingColorClass(diskPct),
		DiskUsedHuman:    diskUsedHuman,
		DiskHardHuman:    humanBytesOrInf(diskHard),

		InodesUsageRounded: strconv.FormatFloat(round2(inodesClamped), 'f', -1, 64),
		InodesOffset:       detailRingOffset(round2(inodesClamped)),
		InodesColorClass:   detailRingColorClass(inodesPct),
		InodesUsedHuman:    humanCount(inodesUsed),
		InodesHardHuman:    humanCountOrInf(inodesHard),

		CPURatioRounded: strconv.FormatFloat(round2(ratioCPU), 'f', -1, 64),
		CPUOffset:       detailRingOffset(ratioCPU),
		CPUColor:        usageColorClass(percentCPU),
		CPUHumanUsage:   humanCPUUsage,
		CPUHumanTotal:   humanCPUTotal,

		RAMPercentRounded: strconv.FormatFloat(round2(percentMem), 'f', -1, 64),
		RAMOffset:         detailRingOffset(percentMem),
		RAMColor:          usageColorClass(percentMem),
		RAMHumanUsage:     humanMemUsage,
		RAMHumanTotal:     humanMemTotal,
	}
}

func stripSuspendedPrefix(username string) string {
	if idx := strings.LastIndex(username, "_"); strings.Contains(username, "SUSPENDED_") && idx != -1 {
		return username[idx+1:]
	}
	return username
}

func readDiskUsageFor(username string) (diskUsage, bool) {
	all := readDiskUsageAll()
	d, ok := all[stripSuspendedPrefix(username)]
	return d, ok
}

// readUsageStatsFor reads the last JSON line of a single user's
// resource_usage.txt.
func readUsageStatsFor(context string) (json.RawMessage, bool) {
	raw, err := os.ReadFile("/home/" + context + "/resource_usage.txt")
	if err != nil {
		return nil, false
	}
	lines := strings.Split(strings.TrimRight(string(raw), "\n"), "\n")
	if len(lines) == 0 || lines[len(lines)-1] == "" {
		return nil, false
	}
	last := lines[len(lines)-1]
	if !json.Valid([]byte(last)) {
		return nil, false
	}
	return json.RawMessage(last), true
}

// readUsageStatsAll reads the last JSON line of every
// /home/*/resource_usage.txt, keyed by each entry's own "user" field --
// done here in Go rather than in the template, since html/template has no
// filter for this kind of lookup.
func readUsageStatsAll() map[string]map[string]interface{} {
	out := map[string]map[string]interface{}{}
	entries, err := os.ReadDir("/home")
	if err != nil {
		return out
	}
	for _, e := range entries {
		if !e.IsDir() {
			continue
		}
		raw, err := os.ReadFile(filepath.Join("/home", e.Name(), "resource_usage.txt"))
		if err != nil {
			continue
		}
		lines := strings.Split(strings.TrimRight(string(raw), "\n"), "\n")
		if len(lines) == 0 || lines[len(lines)-1] == "" {
			continue
		}
		var parsed map[string]interface{}
		if json.Unmarshal([]byte(lines[len(lines)-1]), &parsed) != nil {
			continue
		}
		if user, ok := parsed["user"].(string); ok && user != "" {
			out[user] = parsed
		}
	}
	return out
}

// readUserNotes returns the raw contents of /home/{context}/notes.txt, or
// "" if missing/unreadable.
func readUserNotes(context string) string {
	raw, err := os.ReadFile("/home/" + context + "/notes.txt")
	if err != nil {
		return ""
	}
	return string(raw)
}

// userFeaturesPath is where a user's custom feature-permission overrides are
// stored, one enabled feature name per line -- mirroring notes.txt. Its
// presence means the user has left their plan's feature-set defaults and
// switched to a custom, per-user list.
func userFeaturesPath(context string) string {
	return "/home/" + context + "/features.txt"
}

// notesMapFor builds a map of each user's private note, keyed by each
// user's "server"/context column.
func notesMapFor(users []paneldb.RowMap) map[string]string {
	out := map[string]string{}
	for _, u := range users {
		context, _ := u["server"].(string)
		if context == "" {
			continue
		}
		out[context] = readUserNotes(context)
	}
	return out
}

func (u *Users) resellerScope(r *http.Request) string {
	currentUser := auth.CurrentUser(r)
	if currentUser.Role == "reseller" {
		return currentUser.Username
	}
	return ""
}

type usersListPageData struct {
	webtemplates.Chrome
	Users         []paneldb.RowMap
	Plans         []paneldb.RowMap
	MySQLIsDown   bool
	Widgets       map[string]usageWidgetData
	Notes         map[string]string
	SortCol       string
	SortDirection string
	CSRFToken     string
	Flashes       []auth.Flash
}

// ServeList handles GET /users, /users/.
func (u *Users) ServeList(w http.ResponseWriter, r *http.Request) {
	resellerOwner := u.resellerScope(r)

	users, err := paneldb.GetAllUsers(u.MySQL, resellerOwner)
	mysqlIsDown := err != nil

	var plans []paneldb.RowMap
	sortCol := r.URL.Query().Get("sort")
	direction := r.URL.Query().Get("direction")
	if !mysqlIsDown {
		var allowed []int
		if resellerOwner != "" {
			ids, ok := paneldb.AllowedPlansForReseller(resellerOwner)
			if ok {
				allowed = ids
			}
		}
		plans, _ = paneldb.GetAllPlans(u.MySQL, allowed)

		if sortCol != "" {
			sortRowMaps(users, sortCol, strings.EqualFold(direction, "desc"))
		}
	}

	if r.URL.Query().Get("output") == "json" {
		writeJSON(w, map[string]interface{}{
			"users": users,
			"stats": readUsageStatsAll(),
			"disk":  readDiskUsageAll(),
		})
		return
	}

	statsAll := readUsageStatsAll()
	diskAll := readDiskUsageAll()
	widgets := make(map[string]usageWidgetData, len(users))
	for _, row := range users {
		uname, _ := row["username"].(string)
		if uname == "" {
			continue
		}
		plain := stripSuspendedPrefix(uname)
		d, hasDisk := diskAll[plain]
		widgets[uname] = buildUsageWidget(strings.Contains(uname, "SUSPENDED_"), statsAll[plain], d, hasDisk)
	}

	webtemplates.Render(w, "users_list.html", usersListPageData{
		Chrome:        buildChrome(r, "Users"),
		Users:         users,
		Plans:         plans,
		MySQLIsDown:   mysqlIsDown,
		Widgets:       widgets,
		Notes:         notesMapFor(users),
		SortCol:       sortCol,
		SortDirection: direction,
		CSRFToken:     csrf.Token(r),
		Flashes:       auth.PopFlashes(w, r, u.Sessions),
	})
}

type userDetailPageData struct {
	webtemplates.Chrome
	Username          string
	User              *paneldb.UserData
	Disk              diskUsage
	Notes             string
	Stats             map[string]interface{}
	StatsWidget       detailStatsWidget
	ServerIP          string
	ServerName        string
	DockerCtx         string
	IPType            string
	Locale            string
	CountryCode       string
	EnvData           map[string]string
	PlanCPU           string
	PlanRAM           string
	Services          []composeServiceView
	Features          []map[string]interface{}
	HasCustomFeatures bool
	CSRFToken         string
	Flashes           []auth.Flash
}

var ipv4Re = regexp.MustCompile(`^\d+\.\d+\.\d+\.\d+$`)
var ipv6Re = regexp.MustCompile(`^[0-9a-fA-F:]+$`)

func ipTypeOf(ip string) string {
	switch {
	case ipv4Re.MatchString(ip):
		return "IPv4"
	case ip != "" && ipv6Re.MatchString(ip):
		return "IPv6"
	default:
		return "Invalid"
	}
}

func firstIPFor(username string) string {
	raw, err := os.ReadFile("/etc/openpanel/openpanel/core/users/" + username + "/ip.json")
	if err != nil {
		return ""
	}
	var data map[string]interface{}
	if json.Unmarshal(raw, &data) != nil {
		return ""
	}
	if ips, ok := data["ip_addresses"].([]interface{}); ok && len(ips) > 0 {
		if s, ok := ips[0].(string); ok {
			return s
		}
	}
	if ip, ok := data["ip"].(string); ok {
		return ip
	}
	return ""
}

func userLocale(context string) string {
	raw, err := os.ReadFile("/home/" + context + "/locale")
	if err != nil {
		return ""
	}
	code := strings.ToLower(strings.TrimSpace(string(raw)))
	if len(code) == 2 {
		for _, c := range code {
			if c < 'a' || c > 'z' {
				return ""
			}
		}
		return code
	}
	return ""
}

func readEnvFile(context string) map[string]string {
	out := map[string]string{}
	raw, err := os.ReadFile("/home/" + context + "/.env")
	if err != nil {
		return out
	}
	for _, line := range strings.Split(string(raw), "\n") {
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		key, value, ok := strings.Cut(line, "=")
		if !ok {
			continue
		}
		out[strings.TrimSpace(key)] = strings.Trim(strings.TrimSpace(value), `"`)
	}
	return out
}

var countryLookupClient = &http.Client{Timeout: 2 * time.Second}

func countryCodeForIP(ip string) string {
	if ip == "" {
		return ""
	}
	resp, err := countryLookupClient.Get("https://api.country.is/" + ip)
	if err != nil {
		return ""
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		return ""
	}
	var data struct {
		Country string `json:"country"`
	}
	if json.NewDecoder(resp.Body).Decode(&data) != nil {
		return ""
	}
	return data.Country
}

// ServeDetail handles GET /users/{username}.
func (u *Users) ServeDetail(w http.ResponseWriter, r *http.Request) {
	username := r.PathValue("username")
	currentUser := auth.CurrentUser(r)

	if !paneldb.CheckIfOwnerForUser(u.MySQL, username, currentUser.Username, currentUser.Role) {
		http.Error(w, "Forbidden", http.StatusForbidden)
		return
	}

	userData, err := paneldb.GetUserDataByUsername(u.MySQL, username)
	if err != nil {
		if r.URL.Query().Get("output") == "json" {
			writeJSON(w, map[string]string{"message": "Error: User " + username + " not found", "status": "error"})
			return
		}
		auth.AddFlash(w, r, u.Sessions, "Error: User "+username+" not found", "error")
		http.Redirect(w, r, "/users", http.StatusSeeOther)
		return
	}

	disk, _ := readDiskUsageFor(username)
	stats, hasStats := readUsageStatsFor(userData.Context)
	serverIP := firstIPFor(username)
	if serverIP == "" || ipTypeOf(serverIP) == "Invalid" {
		serverIP = chromeSite.PublicIP
	}
	envData := readEnvFile(userData.Context)

	if r.URL.Query().Get("output") == "json" {
		resp := map[string]interface{}{
			"username":       username,
			"user":           userData,
			"disk":           disk,
			"server_ip":      serverIP,
			"server_name":    serverName(),
			"docker_context": userData.Context,
			"env_data":       envData,
			"ip_type":        ipTypeOf(serverIP),
			"locale":         userLocale(userData.Context),
			"country_code":   countryCodeForIP(serverIP),
		}
		if hasStats {
			resp["stats"] = stats
		} else {
			resp["stats"] = "no data yet"
		}
		writeJSON(w, resp)
		return
	}

	var parsedStats map[string]interface{}
	if hasStats {
		_ = json.Unmarshal(stats, &parsedStats)
	}

	featureSet := "default"
	var planCPU, planRAM string
	if planRow, err := paneldb.GetPlanByID(u.MySQL, strconv.FormatInt(userData.PlanID, 10)); err == nil {
		if fs, ok := planRow["feature_set"].(string); ok && fs != "" {
			featureSet = fs
		}
		planCPU, _ = planRow["cpu"].(string)
		planRAM, _ = planRow["ram"].(string)
	}
	featuresPath := FeatureSetPathForPlan(featureSet, userData.Owner.String)
	hasCustomFeatures := false
	if _, err := os.Stat(userFeaturesPath(userData.Context)); err == nil {
		hasCustomFeatures = true
		featuresPath = userFeaturesPath(userData.Context)
	}
	features, _ := FeaturesForSet(featuresPath)

	webtemplates.Render(w, "user_detail.html", userDetailPageData{
		Chrome:            buildChrome(r, "User: "+stripSuspendedPrefix(username)),
		Username:          username,
		User:              userData,
		Disk:              disk,
		Notes:             readUserNotes(userData.Context),
		Stats:             parsedStats,
		StatsWidget:       buildDetailStatsWidget(strings.Contains(username, "SUSPENDED_"), disk, parsedStats),
		ServerIP:          serverIP,
		ServerName:        serverName(),
		DockerCtx:         userData.Context,
		IPType:            ipTypeOf(serverIP),
		Locale:            userLocale(userData.Context),
		CountryCode:       countryCodeForIP(serverIP),
		EnvData:           envData,
		PlanCPU:           planCPU,
		PlanRAM:           planRAM,
		Services:          composeServicesForUser(u.MySQL, username),
		Features:          features,
		HasCustomFeatures: hasCustomFeatures,
		CSRFToken:         csrf.Token(r),
		Flashes:           auth.PopFlashes(w, r, u.Sessions),
	})
}

func serverName() string {
	name, err := os.Hostname()
	if err != nil {
		return ""
	}
	return name
}

// HandleNotes handles GET/POST /get_user_notes/{username}: GET returns the
// saved private note for the user, POST overwrites it.
func (u *Users) HandleNotes(w http.ResponseWriter, r *http.Request) {
	username := r.PathValue("username")
	currentUser := auth.CurrentUser(r)

	if !paneldb.CheckIfOwnerForUser(u.MySQL, username, currentUser.Username, currentUser.Role) {
		http.Error(w, "Forbidden", http.StatusForbidden)
		return
	}

	userData, err := paneldb.GetUserDataByUsername(u.MySQL, username)
	if err != nil {
		writeJSONError(w, http.StatusNotFound, "User not found")
		return
	}

	if r.Method == http.MethodPost {
		var body struct {
			Notes string `json:"notes"`
		}
		if json.NewDecoder(r.Body).Decode(&body) != nil {
			writeJSONError(w, http.StatusBadRequest, "Invalid content type. Expected JSON.")
			return
		}
		if err := os.WriteFile("/home/"+userData.Context+"/notes.txt", []byte(body.Notes), 0644); err != nil {
			writeJSONError(w, http.StatusInternalServerError, "Failed to save notes")
			return
		}
		writeJSON(w, map[string]string{"message": "Notes for user " + username + " saved successfully."})
		return
	}

	writeJSON(w, map[string]string{"notes": readUserNotes(userData.Context)})
}

// ServeIPs handles GET /json/ips: a map of usernames with a dedicated IP
// address on file to that address.
func (u *Users) ServeIPs(w http.ResponseWriter, r *http.Request) {
	out := map[string]interface{}{}
	matches, _ := filepath.Glob("/etc/openpanel/openpanel/core/users/*/ip.json")
	for _, ipFile := range matches {
		username := filepath.Base(filepath.Dir(ipFile))
		raw, err := os.ReadFile(ipFile)
		if err != nil {
			continue
		}
		var parsed struct {
			IP string `json:"ip"`
		}
		if json.Unmarshal(raw, &parsed) != nil {
			continue
		}
		out[username] = parsed.IP
	}
	writeJSON(w, out)
}

// HandleManage handles POST /user/{action}/{username} for the
// suspend/unsuspend/delete/permissions actions. ('edit' is not yet
// implemented -- see the package doc comment.)
func (u *Users) HandleManage(w http.ResponseWriter, r *http.Request) {
	action := r.PathValue("action")
	username := r.PathValue("username")
	currentUser := auth.CurrentUser(r)

	if !paneldb.CheckIfOwnerForUser(u.MySQL, username, currentUser.Username, currentUser.Role) {
		http.Error(w, "Forbidden", http.StatusForbidden)
		return
	}

	switch action {
	case "suspend":
		success, output := runOpenCLI("", "opencli", "user-suspend", username, "-y")
		if success && strings.Contains(output, "successfully") {
			logUserAction(username, clientIP(r), "Administrator "+currentUser.Username+" suspended user "+username)
			auth.AddFlash(w, r, u.Sessions, "User '"+username+"' suspended successfully", "info")
		} else {
			auth.AddFlash(w, r, u.Sessions, "Error suspending user "+username, "error")
		}

	case "unsuspend":
		// Unlike every other call site in this module (which only strips
		// when "SUSPENDED_" is actually present), this branch strips
		// everything up to the LAST underscore unconditionally whenever one
		// exists at all. If a username itself contains an underscore, this
		// would truncate it incorrectly; preserved as-is rather than
		// silently changed, since opencli's own username validation is the
		// actual source of truth for what usernames can contain, not this
		// handler.
		plain := username
		if idx := strings.LastIndex(username, "_"); idx != -1 {
			plain = username[idx+1:]
		}
		success, output := runOpenCLI("", "opencli", "user-unsuspend", plain)
		if success && strings.Contains(output, "success") {
			logUserAction(plain, clientIP(r), "Administrator "+currentUser.Username+" unsuspended user "+plain)
			auth.AddFlash(w, r, u.Sessions, "User '"+plain+"' unsuspended successfully", "info")
		} else {
			auth.AddFlash(w, r, u.Sessions, "Error unsuspending user "+plain, "error")
		}

	case "delete":
		if r.FormValue("confirmation") != username {
			http.Error(w, "Bad Request", http.StatusBadRequest)
			return
		}
		success, _ := runOpenCLI("", "opencli", "user-delete", username, "-y")
		if success {
			auth.AddFlash(w, r, u.Sessions, "User '"+username+"' deleted successfully", "info")
		} else {
			auth.AddFlash(w, r, u.Sessions, "Error deleting user "+username, "error")
			http.Redirect(w, r, "/users", http.StatusSeeOther)
			return
		}

	case "edit":
		u.handleEditUser(w, r, username, currentUser)
		return

	case "permissions":
		if err := r.ParseForm(); err != nil {
			http.Error(w, "Bad Request", http.StatusBadRequest)
			return
		}
		userData, err := paneldb.GetUserDataByUsername(u.MySQL, username)
		if err != nil {
			auth.AddFlash(w, r, u.Sessions, "Error: User "+username+" not found", "error")
			http.Redirect(w, r, "/users", http.StatusSeeOther)
			return
		}
		keys := make([]string, 0, len(r.PostForm))
		for k := range r.PostForm {
			if k == "csrf_token" {
				continue
			}
			keys = append(keys, k)
		}
		sort.Strings(keys)
		var b strings.Builder
		for _, k := range keys {
			b.WriteString(k + "\n")
		}
		if err := os.WriteFile(userFeaturesPath(userData.Context), []byte(b.String()), 0644); err != nil {
			http.Error(w, "Internal Server Error", http.StatusInternalServerError)
			return
		}
		logUserAction(username, clientIP(r), "Administrator "+currentUser.Username+" updated permissions for user "+username)
		auth.AddFlash(w, r, u.Sessions, "Permissions for '"+username+"' updated successfully", "success")
		http.Redirect(w, r, "/users/"+username+"#permissions", http.StatusSeeOther)
		return

	case "permissions_reset":
		userData, err := paneldb.GetUserDataByUsername(u.MySQL, username)
		if err != nil {
			auth.AddFlash(w, r, u.Sessions, "Error: User "+username+" not found", "error")
			http.Redirect(w, r, "/users", http.StatusSeeOther)
			return
		}
		if err := os.Remove(userFeaturesPath(userData.Context)); err != nil && !os.IsNotExist(err) {
			http.Error(w, "Internal Server Error", http.StatusInternalServerError)
			return
		}
		logUserAction(username, clientIP(r), "Administrator "+currentUser.Username+" reset permissions for user "+username+" to plan defaults")
		auth.AddFlash(w, r, u.Sessions, "Permissions for '"+username+"' reset to plan defaults", "success")
		http.Redirect(w, r, "/users/"+username+"#permissions", http.StatusSeeOther)
		return

	default:
		auth.AddFlash(w, r, u.Sessions, "Invalid user action, valid options are: edit, suspend, unsuspend, delete, permissions, permissions_reset", "error")
	}

	http.Redirect(w, r, "/users", http.StatusSeeOther)
}

