// readUserCreateDefaultsEnv is a distinct, simpler helper from defaults.go's
// readDefaultsEnvGroups() -- it only cares about
// WEB_SERVER/MYSQL_TYPE/VARNISH, reading the same .env file at
// DefaultsEnvPath (defaults.go).
func readUserCreateDefaultsEnv() (webServer, mysqlType string, varnish bool) {
	raw, err := os.ReadFile(DefaultsEnvPath)
	if err != nil {
		return "", "", false
	}
	for _, line := range strings.Split(string(raw), "\n") {
		line = strings.TrimSpace(line)
		switch {
		case strings.HasPrefix(line, "MYSQL_TYPE="):
			mysqlType = strings.Trim(strings.TrimPrefix(line, "MYSQL_TYPE="), `"'`)
		case strings.HasPrefix(line, "WEB_SERVER="):
			webServer = strings.Trim(strings.TrimPrefix(line, "WEB_SERVER="), `"'`)
		case strings.HasPrefix(line, "PROXY_HTTP_PORT="):
			varnish = true
		case strings.HasPrefix(line, "#PROXY_HTTP_PORT="):
			varnish = false
		}
	}
	return
}

// ServeCreateUser handles GET/POST /user/new.
func (u *Users) ServeCreateUser(w http.ResponseWriter, r *http.Request) {
	if r.Method == http.MethodPost {
		u.handleCreateUserPost(w, r)
		return
	}

	resellerOwner := u.resellerScope(r)
	var allowed []int
	if resellerOwner != "" {
		if ids, ok := paneldb.AllowedPlansForReseller(resellerOwner); ok {
			allowed = ids
		}
	}
	plans, err := paneldb.GetAllPlans(u.MySQL, allowed)
	mysqlIsDown := err != nil

	webServer, mysqlType, varnish := readUserCreateDefaultsEnv()

	webtemplates.Render(w, "user_add.html", userCreatePageData{
		Chrome:           buildChrome(r, "Add User"),
		Plans:            plans,
		MySQLIsDown:      mysqlIsDown,
		WebServer:        webServer,
		MySQLType:        mysqlType,
		VarnishEnabled:   varnish,
		Webservers:       userCreateWebservers,
		SQLOptions:       userCreateSQLOptions,
		ResellersEnabled: resellersEnabled(),
		CSRFToken:        csrf.Token(r),
		Flashes:          auth.PopFlashes(w, r, u.Sessions),
	})
}

var userCreateIPv4Re = regexp.MustCompile(`^\d+\.\d+\.\d+\.\d+$`)

// userCreateRun is injectable so tests never shell out to a real opencli
// binary.
var userCreateRun = func(args []string) (*exec.Cmd, error) {
	return exec.Command(args[0], args[1:]...), nil
}

// handleCreateUserPost builds the `opencli user-add` argv from the
// submitted form and streams its stdout back line-by-line as it runs.
func (u *Users) handleCreateUserPost(w http.ResponseWriter, r *http.Request) {
	// The form is submitted as multipart/form-data (the frontend posts a
	// FormData body), not application/x-www-form-urlencoded, so it must be
	// parsed with ParseMultipartForm -- plain ParseForm leaves the body
	// unread for that content type and PostFormValue silently returns "".
	_ = r.ParseMultipartForm(32 << 20)

	email := r.PostFormValue("admin_email")
	username := strings.ToLower(r.PostFormValue("admin_username"))
	password := r.PostFormValue("admin_password")
	planName := r.PostFormValue("plan_name")
	sendMail := r.PostFormValue("send_email")
	webserver := r.PostFormValue("webserver")
	mysqlType := r.PostFormValue("sql_type")
	reseller := r.PostFormValue("reseller")
	slave := r.PostFormValue("slave")
	sshKeyPath := r.PostFormValue("ssh_key_path")

	if email == "" {
		email = username
	}

	command := []string{"opencli", "user-add", username, password, email, planName, "--debug"}

	currentUser := auth.CurrentUser(r)
	if currentUser != nil && currentUser.Role == "reseller" {
		command = append(command, "--reseller="+currentUser.Username)
	} else if reseller != "" {
		command = append(command, "--reseller="+reseller)
	}

	if webserver != "" {
		base := strings.TrimPrefix(strings.ToLower(webserver), "varnish+")
		switch base {
		case "apache", "nginx", "openresty", "openlitespeed":
			command = append(command, "--webserver="+webserver)
		}
	}

	if mysqlType != "" {
		if lower := strings.ToLower(mysqlType); lower == "mysql" || lower == "mariadb" {
			command = append(command, "--sql="+mysqlType)
		}
	}

	if sendMail != "" {
		command = append(command, "--send-email")
	}

	if slave != "" && userCreateIPv4Re.MatchString(slave) {
		command = append(command, "--server="+slave)
	}

	if sshKeyPath != "" {
		command = append(command, "--key="+sshKeyPath)
	}

	flusher, ok := w.(http.Flusher)
	if !ok {
		http.Error(w, "Streaming unsupported", http.StatusInternalServerError)
		return
	}
	w.Header().Set("Content-Type", "text/event-stream")

	if slave != "" && sshKeyPath == "" {
		fmt.Fprintf(w, "Error: SSH key path is required for creating account on %s\n", slave)
		flusher.Flush()
		return
	}

	cmd, err := userCreateRun(command)
	if err != nil {
		fmt.Fprintf(w, "Error: %s\n\n", err.Error())
		flusher.Flush()
		return
	}
	stdout, err := cmd.StdoutPipe()
	if err != nil {
		fmt.Fprintf(w, "Error: %s\n\n", err.Error())
		flusher.Flush()
		return
	}
	// Only stdout is read line-by-line and streamed to the client; stderr
	// is never read from here -- any output opencli sends to stderr is
	// silently discarded, not a bug to "fix" here.
	if err := cmd.Start(); err != nil {
		fmt.Fprintf(w, "Error: %s\n\n", err.Error())
		flusher.Flush()
		return
	}
	scanner := bufio.NewScanner(stdout)
	for scanner.Scan() {
		fmt.Fprintf(w, "%s\n", strings.TrimSpace(scanner.Text()))
		flusher.Flush()
	}
	if err := cmd.Wait(); err != nil {
		fmt.Fprintf(w, "Error: %s\n", err.Error())
		flusher.Flush()
	}
}

func logUserAction(username, ip, action string) {
	username = stripSuspendedPrefix(username)
	username = strings.ReplaceAll(username, " ", "")
	logDir := "/etc/openpanel/openpanel/core/users/" + username
	if err := os.MkdirAll(logDir, 0755); err != nil {
		return
	}
	f, err := os.OpenFile(logDir+"/activity.log", os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0644)
	if err != nil {
		return
	}
	defer f.Close()
	timestamp := time.Now().Format("2006-01-02 15:04:05")
	_, _ = f.WriteString(timestamp + "  " + ip + " " + action + "\n")
}

// ServeResourceUsageHistory handles GET
// /get_resource_usage_history/{username}: the raw, unparsed contents of the
// user's resource_usage.txt file (every historical JSONL snapshot line, not
// just the last one like readUsageStatsFor/ServeDetail use) -- served as
// plain text, NOT JSON, despite what the route's name might suggest.
func (u *Users) ServeResourceUsageHistory(w http.ResponseWriter, r *http.Request) {
	username := stripSuspendedPrefix(r.PathValue("username"))
	currentUser := auth.CurrentUser(r)

	if !paneldb.CheckIfOwnerForUser(u.MySQL, username, currentUser.Username, currentUser.Role) {
		http.Error(w, "Forbidden", http.StatusForbidden)
		return
	}

	context, _ := queryContextByUsername(u.MySQL, username)
	raw, err := os.ReadFile("/home/" + context + "/resource_usage.txt")
	if err != nil {
		http.Error(w, "Resource usage file not found.", http.StatusNotFound)
		return
	}
	w.Header().Set("Content-Type", "text/plain; charset=utf-8")
	w.Write(raw)
}

// userDiskInfoRun is injectable so tests never shell out to a real podman
// binary. Runs `podman system df --format {{json .}}` (summary, not -v --
// podman rejects combining --verbose with --format), whose stdout is one
// independent per-type JSON object per line (Images/Containers/Local
// Volumes/Build Cache, each with Type/Total/Active/Size/Reclaimable).
var userDiskInfoRun = func(context string) (stdout, stderr string, exitCode int, err error) {
	return podmanExecCapture(context, "system", "df", "--format", "{{json .}}")
}

// ServeUserDiskInfo handles GET /client/disk/{username}. Note: unlike most
// other routes in this file, this never strips a "SUSPENDED_..." prefix
// from username here before the ownership check or the context lookup --
// preserved as-is rather than made consistent with the other routes.
func (u *Users) ServeUserDiskInfo(w http.ResponseWriter, r *http.Request) {
	username := r.PathValue("username")
	currentUser := auth.CurrentUser(r)

	if !paneldb.CheckIfOwnerForUser(u.MySQL, username, currentUser.Username, currentUser.Role) {
		http.Error(w, "Forbidden", http.StatusForbidden)
		return
	}

	context, _ := queryContextByUsername(u.MySQL, username)
	stdout, stderr, exitCode, err := userDiskInfoRun(context)
	if err != nil {
		writeJSONStatus(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
		return
	}
	if exitCode != 0 {
		writeJSONStatus(w, http.StatusInternalServerError, map[string]string{
			"error": fmt.Sprintf("podman system df exited with status %d: %s", exitCode, strings.TrimSpace(stderr)),
		})
		return
	}

	data := []json.RawMessage{}
	for _, line := range strings.Split(strings.TrimSpace(stdout), "\n") {
		line = strings.TrimSpace(line)
		if line == "" {
			continue
		}
		if !json.Valid([]byte(line)) {
			writeJSONStatus(w, http.StatusInternalServerError, map[string]string{"error": "invalid JSON in podman output"})
			return
		}
		data = append(data, json.RawMessage(line))
	}
	writeJSON(w, data)
}

// userLogConfig describes one type of user log (activity or logins).
type userLogConfig struct {
	Filename       string
	DownloadSuffix string
	Key            string
	Pattern        *regexp.Regexp
	Fields         []string // nil means the pattern uses named groups instead
}

// userLogConfigs maps each supported log type to its config.
var userLogConfigs = map[string]userLogConfig{
	"activity": {
		Filename:       "activity.log",
		DownloadSuffix: "activity",
		Key:            "user_activity",
		Pattern:        regexp.MustCompile(`^(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2})\s+(\d+\.\d+\.\d+\.\d+)\s+(User|Administrator)\s+(\S+)\s+(.*)`),
		Fields:         []string{"timestamp", "ip_address", "user_type", "user", "action"},
	},
	"logins": {
		Filename:       ".lastlogin",
		DownloadSuffix: "logins",
		Key:            "user_logins",
		Pattern:        regexp.MustCompile(`^IP:\s*(?P<ip>[\d.]+)\s*-\s*Country:\s*(?P<country>\w+)\s*-\s*Login Time:\s*(?P<login_time>[\d\-\s:]+)`),
	},
}

// parseGenericUserLogLine parses one log line using a config's regex
// pattern and field names.
func parseGenericUserLogLine(line string, conf userLogConfig) map[string]string {
	m := conf.Pattern.FindStringSubmatch(line)
	if m == nil {
		return nil
	}
	out := map[string]string{}
	if conf.Fields != nil {
		for i, f := range conf.Fields {
			out[f] = m[i+1]
		}
		return out
	}
	for i, name := range conf.Pattern.SubexpNames() {
		if i == 0 || name == "" {
			continue
		}
		out[name] = m[i]
	}
	return out
}

// capitalizeFirst is good enough for this file's two log_type values
// ("activity"/"logins"): uppercase the first rune, lowercase the rest.
func capitalizeFirst(s string) string {
	if s == "" {
		return s
	}
	return strings.ToUpper(s[:1]) + strings.ToLower(s[1:])
}

// getParsedUserLogJSON returns the reversed (newest-first), regex-parsed
// lines of the user's log file. Its "Log not found" message deliberately
// does NOT mention log_type -- unlike the raw/download 404 branches in
// ServeUserLog below, which do -- since the two code paths handle the
// missing-file case independently and were never unified.
func getParsedUserLogJSON(username string, conf userLogConfig) (int, map[string]interface{}) {
	path := "/etc/openpanel/openpanel/core/users/" + username + "/" + conf.Filename
	raw, err := os.ReadFile(path)
	if err != nil {
		return http.StatusNotFound, map[string]interface{}{"error": "Log not found"}
	}
	lines := strings.Split(string(raw), "\n")
	parsed := []map[string]string{}
	for i := len(lines) - 1; i >= 0; i-- {
		line := strings.TrimSpace(lines[i])
		if line == "" {
			continue
		}
		if p := parseGenericUserLogLine(line, conf); p != nil {
			parsed = append(parsed, p)
		}
	}
	return http.StatusOK, map[string]interface{}{conf.Key: parsed}
}

// ServeUserLog handles GET /json/{userLogType}/{username}. The route is
// meant to serve /json/user-<log_type>/<username> URLs (a literal "user-"
// prefix fused directly onto the <log_type> URL segment), but Go's
// ServeMux can't express a literal-prefix-then-wildcard within one path
// segment, so the "user-" is matched as part of a whole {userLogType}
// segment here and stripped/validated inside the handler instead. The set
// of real reachable URLs is identical, and this doesn't collide with GET
// /json/{resource} since that pattern has one fewer path segment.
func (u *Users) ServeUserLog(w http.ResponseWriter, r *http.Request) {
	rawSegment := r.PathValue("userLogType")
	logType, ok := strings.CutPrefix(rawSegment, "user-")
	if !ok {
		http.NotFound(w, r)
		return
	}
	conf, ok := userLogConfigs[logType]
	if !ok {
		http.NotFound(w, r)
		return
	}

	username := stripSuspendedPrefix(r.PathValue("username"))
	currentUser := auth.CurrentUser(r)
	if !paneldb.CheckIfOwnerForUser(u.MySQL, username, currentUser.Username, currentUser.Role) {
		http.Error(w, "Forbidden", http.StatusForbidden)
		return
	}

	logFilePath := "/etc/openpanel/openpanel/core/users/" + username + "/" + conf.Filename
	download := strings.EqualFold(r.URL.Query().Get("download"), "true")
	rawWanted := strings.EqualFold(r.URL.Query().Get("raw"), "true")

	if download {
		data, err := os.ReadFile(logFilePath)
		if err != nil {
			writeJSONStatus(w, http.StatusNotFound, map[string]string{"error": capitalizeFirst(logType) + " log not found"})
			return
		}
		filename := fmt.Sprintf("%s_%s_%s.log", username, conf.DownloadSuffix, time.Now().Format("2006-01-02_15-04-05"))
		w.Header().Set("Content-Type", "text/plain")
		w.Header().Set("Content-Disposition", `attachment; filename="`+filename+`"`)
		w.Write(data)
		return
	}

	if rawWanted {
		data, err := os.ReadFile(logFilePath)
		if err != nil {
			writeJSONStatus(w, http.StatusNotFound, map[string]string{"error": capitalizeFirst(logType) + " log not found"})
			return
		}
		w.Header().Set("Content-Type", "text/plain; charset=utf-8")
		w.Write(data)
		return
	}

	status, body := getParsedUserLogJSON(username, conf)
	writeJSONStatus(w, status, body)
}

// HandleCustomMessage handles GET/POST
// /get_custom_message_for_user/{username}. Note: like ServeUserDiskInfo
// above, this never strips a "SUSPENDED_..." prefix from username here.
func (u *Users) HandleCustomMessage(w http.ResponseWriter, r *http.Request) {
	username := r.PathValue("username")
	currentUser := auth.CurrentUser(r)

	if !paneldb.CheckIfOwnerForUser(u.MySQL, username, currentUser.Username, currentUser.Role) {
		http.Error(w, "Forbidden", http.StatusForbidden)
		return
	}

	path := "/etc/openpanel/openpanel/core/users/" + username + "/custom_message.html"

	if r.Method == http.MethodPost {
		var body struct {
			CustomMessage *string `json:"custom_message"`
		}
		if json.NewDecoder(r.Body).Decode(&body) != nil {
			writeJSONError(w, http.StatusBadRequest, "Invalid content type. Expected JSON.")
			return
		}
		if err := os.MkdirAll(filepath.Dir(path), 0755); err != nil {
			writeJSONError(w, http.StatusInternalServerError, "Failed to save custom message")
			return
		}
		if body.CustomMessage != nil && *body.CustomMessage != "" {
			os.WriteFile(path, []byte(*body.CustomMessage), 0644)
			writeJSON(w, map[string]string{"message": "Custom message for user " + username + " saved successfully."})
		} else {
			// An empty/missing custom_message doesn't delete the file, it
			// overwrites it with empty content.
			os.WriteFile(path, []byte(""), 0644)
			writeJSON(w, map[string]string{"message": "Custom message for user " + username + " deleted successfully."})
		}
		return
	}

	if raw, err := os.ReadFile(path); err == nil {
		writeJSON(w, map[string]string{"custom_message": string(raw)})
		return
	}
	writeJSON(w, map[string]string{"message": "No custom message found"})
}
